import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.lxr64Vqo.js";const h=JSON.parse('{"title":"Infuse & Vesper Setup (Apple Ecosystem)","description":"","frontmatter":{},"headers":[],"relativePath":"clients/infuse.md","filePath":"clients/infuse.md","lastUpdated":1795172190000}'),s={name:"clients/infuse.md"};function i(n,e,l,d,c,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="infuse-vesper-setup-apple-ecosystem" tabindex="-1">Infuse &amp; Vesper Setup (Apple Ecosystem) <a class="header-anchor" href="#infuse-vesper-setup-apple-ecosystem" aria-label="Permalink to &quot;Infuse &amp; Vesper Setup (Apple Ecosystem)&quot;">​</a></h1><p>NoxMedia features native high-performance integration with both <a href="https://firecore.com/infuse" target="_blank" rel="noreferrer">Firecore Infuse</a> and <a href="https://watchvesper.app" target="_blank" rel="noreferrer">Vesper</a>, providing an Apple-grade home theater experience across Apple TV, iPhone, iPad, Mac, and Apple Vision Pro.</p><p>Through NoxMedia&#39;s <strong>Emulated Jellyfin Bridge</strong>, both players receive full DirectPlay capabilities, 4K HDR10, Dolby Vision passthrough, Spatial Audio, and instant metadata resolution.</p><hr><h2 id="supported-apple-platforms" tabindex="-1">Supported Apple Platforms <a class="header-anchor" href="#supported-apple-platforms" aria-label="Permalink to &quot;Supported Apple Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Player</th><th style="text-align:left;">Supported Devices</th><th style="text-align:left;">Recommended Mode</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Firecore Infuse</strong></td><td style="text-align:left;">Apple TV (tvOS), iPhone &amp; iPad (iOS), Mac (macOS), Apple Vision Pro (visionOS)</td><td style="text-align:left;">Jellyfin Share (Direct Mode in Files)</td></tr><tr><td style="text-align:left;"><strong>Vesper</strong></td><td style="text-align:left;">Mac (macOS), iPhone &amp; iPad (iOS), Apple TV (tvOS)</td><td style="text-align:left;">Jellyfin Server Connection</td></tr></tbody></table><hr><h2 id="infuse-setup-guide" tabindex="-1">Infuse Setup Guide <a class="header-anchor" href="#infuse-setup-guide" aria-label="Permalink to &quot;Infuse Setup Guide&quot;">​</a></h2><h3 id="_1-identify-server-ip" tabindex="-1">1. Identify Server IP <a class="header-anchor" href="#_1-identify-server-ip" aria-label="Permalink to &quot;1. Identify Server IP&quot;">​</a></h3><ol><li>Open NoxMedia on your Android host device.</li><li>Ensure the server toggle is active.</li><li>Note the local address displayed on the dashboard (e.g., <code>http://192.168.1.15:7788</code>).</li></ol><h3 id="_2-connect-in-infuse" tabindex="-1">2. Connect in Infuse <a class="header-anchor" href="#_2-connect-in-infuse" aria-label="Permalink to &quot;2. Connect in Infuse&quot;">​</a></h3><ol><li>Open <strong>Infuse</strong> on your Apple TV, iPhone, iPad, or Mac.</li><li>Navigate to <strong>Settings</strong> (Gear icon) -&gt; <strong>Shares</strong> -&gt; <strong>Add Media...</strong></li><li>Choose <strong>Other...</strong> or select <strong>Jellyfin</strong>.</li><li>Enter the connection parameters: <ul><li><strong>Protocol</strong>: <code>Jellyfin</code> (or <code>Emby</code>)</li><li><strong>Address</strong>: <code>192.168.1.15</code> <em>(enter your device&#39;s actual IP)</em></li><li><strong>Port</strong>: <code>7788</code></li><li><strong>Username</strong>: <code>NoxMedia</code> <em>(or any username)</em></li><li><strong>Password</strong>: <em>(leave blank)</em></li></ul></li><li>Tap <strong>Save</strong>. Infuse will connect to your server immediately.</li></ol><h3 id="_3-direct-mode-vs-library-mode" tabindex="-1">3. Direct Mode vs. Library Mode <a class="header-anchor" href="#_3-direct-mode-vs-library-mode" aria-label="Permalink to &quot;3. Direct Mode vs. Library Mode&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Use Direct Mode (Files Tab) in Infuse.</strong> In Infuse Settings -&gt; <strong>Library</strong>, do not enable full background crawling on the NoxMedia share. Infuse&#39;s background crawler attempts to recursively inspect every single item at once, which can trigger network timeouts. Direct Mode (browsing via the <strong>Files</strong> tab) queries metadata on-demand with instant zero-latency responses.</p></div><h3 id="_4-custom-shelves-home-screen-favorites" tabindex="-1">4. Custom Shelves &amp; Home Screen Favorites <a class="header-anchor" href="#_4-custom-shelves-home-screen-favorites" aria-label="Permalink to &quot;4. Custom Shelves &amp; Home Screen Favorites&quot;">​</a></h3><ol><li>Open Infuse and navigate to the <strong>Files</strong> tab.</li><li>Select the <strong>NoxMedia</strong> share.</li><li>You will see default libraries (<strong>Movies</strong>, <strong>TV Shows</strong>, <strong>Anime</strong>) alongside all your custom AI-curated catalogs (e.g., <em>Murder Mystery Dark</em>, <em>Oscar Winners</em>, <em>Sci-Fi Universe</em>).</li><li>Long-press or select the <strong>Star</strong> icon on any custom shelf to mark it as a <strong>Favorite</strong>.</li><li>Starred shelves appear as dedicated horizontal rows on your Apple TV and iOS Home Screen.</li></ol><hr><h2 id="vesper-setup-guide" tabindex="-1">Vesper Setup Guide <a class="header-anchor" href="#vesper-setup-guide" aria-label="Permalink to &quot;Vesper Setup Guide&quot;">​</a></h2><p><a href="https://watchvesper.app" target="_blank" rel="noreferrer">Vesper</a> is an ultra-fast, modern media player designed specifically for macOS, iOS, and tvOS with a streamlined, minimalist interface.</p><h3 id="connection-steps" tabindex="-1">Connection Steps: <a class="header-anchor" href="#connection-steps" aria-label="Permalink to &quot;Connection Steps:&quot;">​</a></h3><ol><li>Open <strong>Vesper</strong> on your Mac, iPhone, iPad, or Apple TV.</li><li>Go to <strong>Settings</strong> -&gt; <strong>Servers</strong> -&gt; <strong>Add Server</strong>.</li><li>Select <strong>Jellyfin</strong>.</li><li>Enter your host server details: <ul><li><strong>Server URL</strong>: <code>http://192.168.1.15:7788</code></li><li><strong>Username</strong>: <code>NoxMedia</code></li><li><strong>Password</strong>: <em>(leave blank)</em></li></ul></li><li>Confirm the connection. Vesper will synchronize your libraries and display posters, episode layouts, and custom shelves.</li></ol><hr><h2 id="codec-audio-capabilities" tabindex="-1">Codec &amp; Audio Capabilities <a class="header-anchor" href="#codec-audio-capabilities" aria-label="Permalink to &quot;Codec &amp; Audio Capabilities&quot;">​</a></h2><ul><li><strong>DirectPlay Everything</strong>: Infuse and Vesper handle HEVC/H.265, AV1, VP9, H.264, DTS-HD, Dolby TrueHD Atmos, and EAC3 natively without server-side transcoding.</li><li><strong>Embedded Tracks</strong>: Switch between multiple audio streams and subtitle tracks on the fly.</li><li><strong>Dolby Vision &amp; HDR10+</strong>: Automatically mapped to match display profiles on Apple TV 4K, ProMotion iPads, and Liquid Retina XDR displays.</li></ul>',24)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
